import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Module: handl_platform","description":"","frontmatter":{},"headers":[],"relativePath":"api/host/handl_platform/handl_platform.md","filePath":"api/host/handl_platform/handl_platform.md"}`),a={name:`api/host/handl_platform/handl_platform.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p><strong>handl_platform</strong></p><h1 id="module-handl-platform" tabindex="-1">Module: handl_platform <a class="header-anchor" href="#module-handl-platform" aria-label="Permalink to “Module: handl_platform”">​</a></h1><h2 id="contents" tabindex="-1">Contents <a class="header-anchor" href="#contents" aria-label="Permalink to “Contents”">​</a></h2><p><strong>Modules</strong></p><ul><li><a href="#ast-node"><code>ast_node</code></a> - Generic, composable AST node.</li><li><a href="#boundary"><code>boundary</code></a> - Types for describing runtime isolation boundaries.</li><li><a href="#build"><code>build</code></a> - Generic build operation and rule acceptor.</li><li><a href="#capability"><code>capability</code></a> - Capability identifiers and metadata.</li><li><a href="#compile"><code>compile</code></a> - Generic compile operation and rule acceptor.</li><li><a href="#config"><code>config</code></a> - Runtime configuration and appliers.</li><li><a href="#error"><code>error</code></a> - Platform error types.</li><li><a href="#eval"><code>eval</code></a> - Generic evaluation operation and rule acceptor.</li><li><a href="#format"><code>format</code></a> - Generic format operation and rule acceptor.</li><li><a href="#host"><code>host</code></a> - Runtime implementations that coordinate plugins and kits.</li><li><a href="#kit"><code>kit</code></a> - Kit manifests and registries.</li><li><a href="#lint"><code>lint</code></a> - Generic lint operation and rule acceptor.</li><li><a href="#manifest"><code>manifest</code></a> - Plugin manifest definitions and dependency declarations.</li><li><a href="#options"><code>options</code></a> - Plugin-provided option schemas and resolved values.</li><li><a href="#plugin"><code>plugin</code></a> - Plugin traits, registries, and built-in plugin implementations.</li><li><a href="#plugin-model"><code>plugin_model</code></a> - Foundational composable plugin types.</li><li><a href="#resolve"><code>resolve</code></a> - Plugin composition resolution.</li><li><a href="#vm"><code>vm</code></a> - Composable VM wrapper over the unified value space.</li></ul><hr><h2 id="module-ast-node" tabindex="-1">Module: ast_node <a class="header-anchor" href="#module-ast-node" aria-label="Permalink to “Module: ast_node”">​</a></h2><p>Generic, composable AST node. Generic, composable AST node type.</p><h2 id="module-boundary" tabindex="-1">Module: boundary <a class="header-anchor" href="#module-boundary" aria-label="Permalink to “Module: boundary”">​</a></h2><p>Types for describing runtime isolation boundaries. Boundary types describing isolation and deployment units.</p><h2 id="module-build" tabindex="-1">Module: build <a class="header-anchor" href="#module-build" aria-label="Permalink to “Module: build”">​</a></h2><p>Generic build operation and rule acceptor. Generic build operation and <code>BasicBuilder</code> rule acceptor.</p><p>This module defines the <code>Build</code> operation, <code>BuildBehavior</code> trait, and a default <code>BasicBuilder</code> <code>RuleAcceptor</code> plugin. The <code>BasicBuilder</code> has no knowledge of concrete build targets; it dispatches to registered <code>BuildBehavior</code> rules keyed by <code>AstNode.kind</code>.</p><h2 id="module-capability" tabindex="-1">Module: capability <a class="header-anchor" href="#module-capability" aria-label="Permalink to “Module: capability”">​</a></h2><p>Capability identifiers and metadata. Capability identifiers and metadata.</p><h2 id="module-compile" tabindex="-1">Module: compile <a class="header-anchor" href="#module-compile" aria-label="Permalink to “Module: compile”">​</a></h2><p>Generic compile operation and rule acceptor. Generic compile operation and <code>BasicCompiler</code> rule acceptor.</p><p>This module defines the <code>Compile</code> operation, <code>CompileBehavior</code> trait, and a default <code>BasicCompiler</code> <code>RuleAcceptor</code> plugin. The <code>BasicCompiler</code> has no knowledge of concrete compilation targets; it dispatches to registered <code>CompileBehavior</code> rules keyed by <code>AstNode.kind</code>.</p><h2 id="module-config" tabindex="-1">Module: config <a class="header-anchor" href="#module-config" aria-label="Permalink to “Module: config”">​</a></h2><p>Runtime configuration and appliers. Runtime configuration and appliers.</p><p>This module provides the in-memory description of which kits and plugins a host should load, what to exclude, and which option overrides to apply. It also defines the <code>HostApplier</code> trait and a <code>.handl.toml</code> backed applier.</p><h2 id="module-error" tabindex="-1">Module: error <a class="header-anchor" href="#module-error" aria-label="Permalink to “Module: error”">​</a></h2><p>Platform error types. Platform error types.</p><h2 id="module-eval" tabindex="-1">Module: eval <a class="header-anchor" href="#module-eval" aria-label="Permalink to “Module: eval”">​</a></h2><p>Generic evaluation operation and rule acceptor. Generic evaluation operation and <code>BasicEvaluator</code> rule acceptor.</p><p>This module defines the <code>Eval</code> operation, <code>EvalBehavior</code> trait, and a default <code>BasicEvaluator</code> <code>RuleAcceptor</code> plugin. The <code>BasicEvaluator</code> has no knowledge of concrete language builtins; it dispatches to registered <code>EvalBehavior</code> rules keyed by <code>AstNode.kind</code>.</p><p>Unlike other operations, <code>Eval</code> carries an [<code>EvalContext</code>] inside the [<code>EvalRequest</code>]. The context holds variable scopes, resource limits, a call counter, and an [<code>EvaluatorCallback</code>] handle that lets recursive rules evaluate child AST nodes by calling <code>req.ctx.eval(&amp;child)</code>.</p><p>Exec-control cross-cutting concerns (limits, tracing, caching, sandboxing) are handled by the lightweight [<code>ExecControl</code>] two-hook trait, invoked by <code>BasicEvaluator</code> before and after each dispatch.</p><h2 id="module-format" tabindex="-1">Module: format <a class="header-anchor" href="#module-format" aria-label="Permalink to “Module: format”">​</a></h2><p>Generic format operation and rule acceptor. Generic format operation and <code>BasicFormatter</code> rule acceptor.</p><p>This module defines the <code>Format</code> operation, <code>FormatBehavior</code> trait, and a default <code>BasicFormatter</code> <code>RuleAcceptor</code> plugin. The <code>BasicFormatter</code> has no knowledge of concrete surface syntax; it dispatches to registered <code>FormatBehavior</code> rules keyed by <code>AstNode.kind</code>.</p><h1 id="role-after-adr-0095" tabindex="-1">Role after ADR-0095 <a class="header-anchor" href="#role-after-adr-0095" aria-label="Permalink to “Role after ADR-0095”">​</a></h1><p>The canonical formatter is the <strong>staged engine pipeline</strong> in <code>hnl-engine-fmt</code> (layout → render → post-process), surfaced by <code>handl-plugin-ext-fmt</code> (<code>format_source</code>/<code>check_source</code>/<code>format_ast</code>). Those crates depend on this crate, so <code>platform</code> <strong>cannot</strong> dispatch to the engine here (dependency direction). This <code>Format</code> capability therefore remains the <strong>generic per-node contribution seam</strong> of ADR-0014/ADR-0029: hosts and kits register <code>FormatBehavior</code> rules for individual node kinds. It is not the canonical formatting path — that is <code>FormatEngine</code>/<code>plugin-ext-fmt</code>. Keeping the two honest (documented) avoids a disconnected facade.</p><h2 id="module-host" tabindex="-1">Module: host <a class="header-anchor" href="#module-host" aria-label="Permalink to “Module: host”">​</a></h2><p>Runtime implementations that coordinate plugins and kits. Runtime implementations that coordinate plugins and kits.</p><h2 id="module-kit" tabindex="-1">Module: kit <a class="header-anchor" href="#module-kit" aria-label="Permalink to “Module: kit”">​</a></h2><p>Kit manifests and registries. Kit manifests and registries.</p><h2 id="module-lint" tabindex="-1">Module: lint <a class="header-anchor" href="#module-lint" aria-label="Permalink to “Module: lint”">​</a></h2><p>Generic lint operation and rule acceptor. Generic lint operation and <code>BasicLinter</code> rule acceptor.</p><p>This module defines the <code>Lint</code> operation, <code>LintBehavior</code> trait, and a default <code>BasicLinter</code> <code>RuleAcceptor</code> plugin. The <code>BasicLinter</code> has no knowledge of concrete diagnostic rules; it dispatches to registered <code>LintBehavior</code> rules keyed by <code>AstNode.kind</code>.</p><h2 id="module-manifest" tabindex="-1">Module: manifest <a class="header-anchor" href="#module-manifest" aria-label="Permalink to “Module: manifest”">​</a></h2><p>Plugin manifest definitions and dependency declarations. Plugin manifest definitions and dependency declarations.</p><h2 id="module-options" tabindex="-1">Module: options <a class="header-anchor" href="#module-options" aria-label="Permalink to “Module: options”">​</a></h2><p>Plugin-provided option schemas and resolved values. Plugin-provided option schemas and resolved option values.</p><p>The <code>OptionsPlugin</code> collects <code>OptionSchema</code> contributions from other plugins and can resolve them into a <code>ResolvedOptions</code> map that operations query at runtime.</p><h2 id="module-plugin" tabindex="-1">Module: plugin <a class="header-anchor" href="#module-plugin" aria-label="Permalink to “Module: plugin”">​</a></h2><p>Plugin traits, registries, and built-in plugin implementations. Plugin traits, registries, and built-in plugin implementations.</p><h2 id="module-plugin-model" tabindex="-1">Module: plugin_model <a class="header-anchor" href="#module-plugin-model" aria-label="Permalink to “Module: plugin_model”">​</a></h2><p>Foundational composable plugin types. Foundational composable plugin types.</p><p>This module defines the base traits and context used by the <code>handl-platform</code> composition model: <code>Contribution</code>, <code>RuleAcceptor</code>, <code>Operation</code>, <code>Behavior</code>, and <code>ContributionContext</code>.</p><h2 id="module-resolve" tabindex="-1">Module: resolve <a class="header-anchor" href="#module-resolve" aria-label="Permalink to “Module: resolve”">​</a></h2><p>Plugin composition resolution. Plugin composition resolution.</p><h2 id="module-vm" tabindex="-1">Module: vm <a class="header-anchor" href="#module-vm" aria-label="Permalink to “Module: vm”">​</a></h2><p>Composable VM wrapper over the unified value space. Minimal, composable VM piece for the handl platform.</p><p>The <code>Vm</code> is generic over the host and environment types so that the concrete <code>DefaultHost</code> and <code>Env</code> are no longer hard-coded. Any <code>CallableLookup</code> implementation can be supplied instead.</p>`,55)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};